-- WoW Chat Translator: 툴팁 문장표·패턴 (자동 생성 - tools/build_tooltip.py)
local ADDON, ns = ...
ns.TipText = {
	["places a fishing rack that grants the ability to catch uncommon fish for # hr, provides fishing skill lures, and provides all of the benefits of a fish bowl"] = { ko = "낚시 선반을 설치합니다. {1}시간 동안 고급 물고기를 낚을 수 있고, 낚시 숙련도를 올려 주는 미끼를 제공하며, 물고기 그릇의 모든 효과를 받습니다.", zhCN = "放置一个钓鱼架，{1}小时内可以钓到优秀品质的鱼，提供提升钓鱼技能的鱼饵，并获得鱼碗的全部效果。", zhTW = "放置一個釣魚架，{1}小時內可以釣到優秀品質的魚，提供提升釣魚技能的魚餌，並獲得魚碗的全部效果。", ru = "Устанавливает рыболовную стойку: в течение {1} ч позволяет ловить необычную рыбу, даёт приманки для навыка рыбной ловли и все преимущества рыбной чаши." },
	["requires a campfire nearby"] = { ko = "근처에 모닥불이 필요합니다.", zhCN = "需要附近有篝火。", zhTW = "需要附近有篝火。", ru = "Требуется костёр поблизости." },
	["may be placed over a fish bowl to replace it"] = { ko = "물고기 그릇 위에 설치하면 그릇을 대체합니다.", zhCN = "可以放置在鱼碗上以替换它。", zhTW = "可以放置在魚碗上以替換它。", ru = "Можно установить поверх рыбной чаши, чтобы заменить её." },
	["all camping features share a cooldown of # hr"] = { ko = "모든 캠핑 기능은 재사용 대기시간 {1}시간을 공유합니다.", zhCN = "所有野营功能共享{1}小时的冷却时间。", zhTW = "所有野營功能共享{1}小時的冷卻時間。", ru = "Все функции лагеря имеют общее время восстановления {1} ч." },
	["requires a campfire"] = { ko = "모닥불이 필요합니다.", zhCN = "需要篝火。", zhTW = "需要篝火。", ru = "Требуется костёр." },
	["requires a campfire nearby to be used"] = { ko = "근처에 모닥불이 있어야 사용할 수 있습니다.", zhCN = "附近有篝火时才能使用。", zhTW = "附近有篝火時才能使用。", ru = "Можно использовать только рядом с костром." },
	["right click to open"] = { ko = "오른쪽 클릭으로 엽니다", zhCN = "右键点击打开", zhTW = "右鍵點選開啟", ru = "ПКМ, чтобы открыть" },
	["<right click to open>"] = { ko = "<오른쪽 클릭으로 열기>", zhCN = "<右键点击打开>", zhTW = "<右鍵點選開啟>", ru = "<ПКМ, чтобы открыть>" },
	["right click to read"] = { ko = "오른쪽 클릭으로 읽습니다", zhCN = "右键点击阅读", zhTW = "右鍵點選閱讀", ru = "ПКМ, чтобы прочитать" },
	["<right click to read>"] = { ko = "<오른쪽 클릭으로 읽기>", zhCN = "<右键点击阅读>", zhTW = "<右鍵點選閱讀>", ru = "<ПКМ, чтобы прочитать>" },
	["this item begins a quest"] = { ko = "이 아이템으로 퀘스트를 시작합니다", zhCN = "该物品将触发一个任务", zhTW = "該物品將觸發一個任務", ru = "Этот предмет позволяет получить задание" },
	["quest item"] = { ko = "퀘스트 아이템", zhCN = "任务物品", zhTW = "任務物品", ru = "Предмет для задания" },
	["binds when picked up"] = { ko = "획득 시 귀속", zhCN = "拾取后绑定", zhTW = "拾取後繫結", ru = "Персональный при получении" },
	["binds when equipped"] = { ko = "착용 시 귀속", zhCN = "装备后绑定", zhTW = "裝備後繫結", ru = "Становится персональным при надевании" },
	["binds when used"] = { ko = "사용 시 귀속", zhCN = "使用后绑定", zhTW = "使用後繫結", ru = "Становится персональным при использовании" },
	["unique"] = { ko = "고유 아이템", zhCN = "唯一", zhTW = "唯一", ru = "Уникальный" },
	["unique-equipped"] = { ko = "고유 장착", zhCN = "唯一装备", zhTW = "唯一裝備", ru = "Уникальный (используемый)" },
	["conjured item"] = { ko = "창조된 아이템", zhCN = "魔法制造的物品", zhTW = "魔法制造的物品", ru = "Сотворённый предмет" },
	["must remain seated while eating"] = { ko = "음식을 먹는 동안 앉아 있어야 합니다.", zhCN = "进食时必须保持坐姿。", zhTW = "進食時必須保持坐姿。", ru = "Во время еды нужно сидеть." },
	["must remain seated while drinking"] = { ko = "마시는 동안 앉아 있어야 합니다.", zhCN = "喝水时必须保持坐姿。", zhTW = "喝水時必須保持坐姿。", ru = "Во время питья нужно сидеть." },
	["must remain seated while eating and drinking"] = { ko = "먹고 마시는 동안 앉아 있어야 합니다.", zhCN = "进食和喝水时必须保持坐姿。", zhTW = "進食和喝水時必須保持坐姿。", ru = "Во время еды и питья нужно сидеть." },
	["can only be used outdoors"] = { ko = "야외에서만 사용할 수 있습니다.", zhCN = "只能在室外使用。", zhTW = "只能在室外使用。", ru = "Можно использовать только под открытым небом." },
	["cannot be used in combat"] = { ko = "전투 중에는 사용할 수 없습니다.", zhCN = "战斗中无法使用。", zhTW = "戰鬥中無法使用。", ru = "Нельзя использовать в бою." },
	["can only be used out of combat"] = { ko = "전투 중이 아닐 때만 사용할 수 있습니다.", zhCN = "只能在非战斗状态下使用。", zhTW = "只能在非戰鬥狀態下使用。", ru = "Можно использовать только вне боя." },
	["only usable in battlegrounds"] = { ko = "전장에서만 사용할 수 있습니다.", zhCN = "只能在战场中使用。", zhTW = "只能在戰場中使用。", ru = "Можно использовать только на полях боя." },
	["duration: # min"] = { ko = "지속시간: {1}분", zhCN = "持续时间：{1}分钟", zhTW = "持續時間：{1}分鐘", ru = "Длительность: {1} мин" },
	["duration: # hr"] = { ko = "지속시간: {1}시간", zhCN = "持续时间：{1}小时", zhTW = "持續時間：{1}小時", ru = "Длительность: {1} ч" },
	["duration: # sec"] = { ko = "지속시간: {1}초", zhCN = "持续时间：{1}秒", zhTW = "持續時間：{1}秒", ru = "Длительность: {1} сек" },
	["lasts # min"] = { ko = "{1}분 동안 지속됩니다.", zhCN = "持续{1}分钟。", zhTW = "持續{1}分鐘。", ru = "Действует {1} мин." },
	["lasts # hr"] = { ko = "{1}시간 동안 지속됩니다.", zhCN = "持续{1}小时。", zhTW = "持續{1}小時。", ru = "Действует {1} ч." },
	["lasts # sec"] = { ko = "{1}초 동안 지속됩니다.", zhCN = "持续{1}秒。", zhTW = "持續{1}秒。", ru = "Действует {1} сек." },
	["requires a nearby campfire or cooking fire"] = { ko = "근처에 모닥불이나 요리용 불이 필요합니다.", zhCN = "需要附近有篝火或烹饪用火。", zhTW = "需要附近有篝火或烹飪用火。", ru = "Требуется костёр или очаг поблизости." },
	["requires a nearby anvil"] = { ko = "근처에 모루가 필요합니다.", zhCN = "需要附近有铁砧。", zhTW = "需要附近有鐵砧。", ru = "Требуется наковальня поблизости." },
	["requires a nearby forge"] = { ko = "근처에 화로가 필요합니다.", zhCN = "需要附近有熔炉。", zhTW = "需要附近有熔爐。", ru = "Требуется горн поблизости." },
	["classes: warrior"] = { ko = "직업: 전사", zhCN = "职业：战士", zhTW = "職業：戰士", ru = "Классы: воин" },
	["not available yet"] = { ko = "아직 사용할 수 없습니다.", zhCN = "尚不可用。", zhTW = "尚不可用。", ru = "Пока недоступно." },
	["coming soon"] = { ko = "곧 추가됩니다.", zhCN = "即将推出。", zhTW = "即將推出。", ru = "Скоро." },
	["shapeshift into cat form, increasing attack power by # plus agility"] = { ko = "표범 변신을 합니다. 전투력이 {1} + 민첩만큼 증가합니다.", zhCN = "变形为猎豹形态，攻击强度提高{1}点加上敏捷值。", zhTW = "變形為獵豹形態，攻擊強度提高{1}點加上敏捷值。", ru = "Превращает в облик кошки, увеличивая силу атаки на {1} плюс ловкость." },
	["also protects the caster from polymorph effects and allows the use of various cat abilities"] = { ko = "또한 변이 효과에 걸리지 않으며 여러 표범 기술을 사용할 수 있습니다.", zhCN = "同时使施法者免疫变形术效果，并可以使用各种猎豹技能。", zhTW = "同時使施法者免疫變形術效果，並可以使用各種獵豹技能。", ru = "Также защищает от эффектов превращения и позволяет использовать способности кошки." },
	["also protects the caster from polymorph effects and allows the use of various bear abilities"] = { ko = "또한 변이 효과에 걸리지 않으며 여러 곰 기술을 사용할 수 있습니다.", zhCN = "同时使施法者免疫变形术效果，并可以使用各种熊形态技能。", zhTW = "同時使施法者免疫變形術效果，並可以使用各種熊形態技能。", ru = "Также защищает от эффектов превращения и позволяет использовать способности медведя." },
	["the act of shapeshifting frees the caster of polymorph and movement impairing effects"] = { ko = "변신하는 순간 변이 효과와 이동 방해 효과가 풀립니다.", zhCN = "变形的同时解除施法者身上的变形术和移动限制效果。", zhTW = "變形的同時解除施法者身上的變形術和移動限制效果。", ru = "При смене облика снимаются эффекты превращения и замедления." },
	["also protects the caster from polymorph effects"] = { ko = "또한 변이 효과에 걸리지 않습니다.", zhCN = "同时使施法者免疫变形术效果。", zhTW = "同時使施法者免疫變形術效果。", ru = "Также защищает от эффектов превращения." },
	["gives you a #% chance to gain # rage when shapeshifting into bear form or dire bear form"] = { ko = "곰 변신이나 광포한 곰 변신을 할 때 {1}% 확률로 분노를 {2} 얻습니다.", zhCN = "变形为熊形态或巨熊形态时，有{1}%的几率获得{2}点怒气。", zhTW = "變形為熊形態或巨熊形態時，有{1}%的機率獲得{2}點怒氣。", ru = "При превращении в облик медведя или лютого медведя с вероятностью {1}% вы получаете {2} ед. ярости." },
	["shapeshifting into cat form restores #% of the energy you had when last in cat form, plus # energy per sec spent outside cat form, up to # energy"] = { ko = "표범 변신을 하면 마지막으로 표범 변신 상태였을 때 기력의 {1}%를 되찾고, 표범 변신 밖에서 보낸 1초마다 기력을 {2}씩 더 얻습니다. (최대 기력 {3})", zhCN = "变形为猎豹形态时，恢复上次处于猎豹形态时{1}%的能量，并且在猎豹形态外每过1秒额外获得{2}点能量，最多{3}点能量。", zhTW = "變形為獵豹形態時，恢復上次處於獵豹形態時{1}%的能量，並且在獵豹形態外每過1秒額外獲得{2}點能量，最多{3}點能量。", ru = "При превращении в облик кошки восстанавливается {1}% энергии, которая была в прошлый раз в облике кошки, плюс {2} ед. энергии за каждую секунду вне облика кошки (не более {3} ед.)." },
	["bear form and dire bear form forfeit this energy and halt its restoration while active"] = { ko = "곰 변신과 광포한 곰 변신 중에는 이 기력을 잃고 회복도 멈춥니다.", zhCN = "处于熊形态和巨熊形态时会失去这些能量，并停止恢复。", zhTW = "處於熊形態和巨熊形態時會失去這些能量，並停止恢復。", ru = "В облике медведя и лютого медведя эта энергия теряется, а её восстановление прекращается." },
	["reduces the cooldown of your shifting power spell by # sec"] = { ko = "변신의 힘 주문의 재사용 대기시간이 {1}초 감소합니다.", zhCN = "使你的变形之力法术的冷却时间缩短{1}秒。", zhTW = "使你的變形之力法術的冷卻時間縮短{1}秒。", ru = "Сокращает время восстановления заклинания «Сила смены облика» на {1} сек." },
	["increases the critical strike damage bonus of your melee abilities by #% and increases your spell healing by #% of your intellect"] = { ko = "근접 기술의 치명타 피해 보너스가 {1}% 증가하고, 주문 치유량이 지능의 {2}%만큼 증가합니다.", zhCN = "使你的近战技能的致命一击伤害加成提高{1}%，并使你的法术治疗效果提高相当于你智力{2}%的数值。", zhTW = "使你的近戰技能的致命一擊傷害加成提高{1}%，並使你的法術治療效果提高相當於你智力{2}%的數值。", ru = "Увеличивает бонус к урону от критических ударов ваших способностей ближнего боя на {1}% и повышает исцеление заклинаниями на {2}% от вашего интеллекта." },
	["bite the target, dealing #% normal damage plus # and generating a high amount of threat"] = { ko = "대상을 물어뜯어 무기 피해의 {1}% + {2}의 피해를 주고 위협 수준을 크게 높입니다.", zhCN = "撕咬目标，造成{1}%的普通伤害外加{2}点伤害，并产生大量威胁值。", zhTW = "撕咬目標，造成{1}%的普通傷害外加{2}點傷害，併產生大量威脅值。", ru = "Кусает цель, нанося {1}% обычного урона плюс {2} ед. и создавая большой уровень угрозы." },
	["shapeshift into moonkin form, increasing omen of clarity's chance to trigger by #%, armor contribution from items by #%, and all party members within # yards have their critical strike chance increased by #%, exclusive with leader of the pack"] = { ko = "달빛야수 변신을 합니다. 청명의 전조 발동 확률이 {1}%, 아이템 방어도가 {2}% 증가하고, {3}미터 내 모든 파티원의 치명타율이 {4}% 증가합니다. (무리의 우두머리와 중복되지 않음)", zhCN = "变形为枭兽形态，使清晰预兆的触发几率提高{1}%，物品提供的护甲值提高{2}%，并使{3}码范围内所有队友的致命一击几率提高{4}%，与兽群领袖效果不叠加。", zhTW = "變形為梟獸形態，使清晰預兆的觸發機率提高{1}%，物品提供的護甲值提高{2}%，並使{3}碼範圍內所有隊友的致命一擊機率提高{4}%，與獸群領袖效果不疊加。", ru = "Превращает в облик лунного совуха: шанс срабатывания «Ясности мысли» +{1}%, броня от предметов +{2}%, у всех членов группы в радиусе {3} м шанс критического удара +{4}% (не суммируется с «Вожаком стаи»)." },
	["also protects the caster from polymorph effects and prevents the use of healing spells"] = { ko = "또한 변이 효과에 걸리지 않지만 치유 주문은 사용할 수 없습니다.", zhCN = "同时使施法者免疫变形术效果，但无法使用治疗法术。", zhTW = "同時使施法者免疫變形術效果，但無法使用治療法術。", ru = "Также защищает от эффектов превращения, но не позволяет использовать исцеляющие заклинания." },
	["unpacks a first aid kit that allows you and others sitting nearby to gain # increased stamina, mutually exclusive with power word: fortitude"] = { ko = "응급치료 도구를 펼칩니다. 근처에 앉은 자신과 다른 플레이어의 체력이 {1}만큼 증가합니다. 신의 권능: 인내와 동시에 적용되지 않습니다." },
	["ignites an incense candle that allows you and others sitting nearby to gain # increased intellect, mutually exclusive with arcane intellect"] = { ko = "향초를 켭니다. 근처에 앉은 자신과 다른 플레이어의 지능이 {1}만큼 증가합니다. 신비한 지능과 동시에 적용되지 않습니다." },
	["raise the severed head of roogug, horrifying and silencing all swine within # yds for # sec"] = { ko = "루구그의 잘린 머리를 들어 올려 {1}미터 내 모든 가시멧돼지를 {2}초 동안 공포에 질리게 하고 침묵시킵니다.", zhCN = "举起鲁古格的断头，使{1}码内所有野猪恐惧并沉默，持续{2}秒。", zhTW = "舉起魯古格的斷頭，使{1}碼內所有野豬恐懼並沉默，持續{2}秒。", ru = "Поднимает отрубленную голову Ругуга, вызывая ужас и немоту у всех свиней в радиусе {1} м на {2} сек." },
	["chance on damaging spell to allow #% of your mana regeneration to continue while casting for # sec"] = { ko = "공격 주문 사용 시 일정 확률로 {2}초 동안 시전 중에도 마나 회복량의 {1}%가 계속 회복됩니다.", zhCN = "伤害性法术有一定几率使施法时仍保持{1}%的法力恢复，持续{2}秒。", zhTW = "傷害性法術有一定機率使施法時仍保持{1}%的法力恢復，持續{2}秒。", ru = "При использовании наносящего урон заклинания есть вероятность продолжить {1}% восполнения маны во время произнесения заклинаний в течение {2} сек." },
	["mana regen amount is doubled in strongholds and cities"] = { ko = "요새와 도시에서는 마나 회복량이 두 배가 됩니다.", zhCN = "在要塞和城市中，法力恢复量翻倍。", zhTW = "在要塞和城市中，法力恢復量翻倍。", ru = "В крепостях и городах объём восполнения маны удваивается." },
	["chance on damaging spell to summon an arcane elemental to aid you in combat"] = { ko = "공격 주문 사용 시 일정 확률로 전투를 돕는 비전 정령을 소환합니다.", zhCN = "伤害性法术有一定几率召唤一个奥术元素协助战斗。", zhTW = "傷害性法術有一定機率召喚一個奧術元素協助戰鬥。", ru = "При использовании наносящего урон заклинания есть вероятность призвать чародейского элементаля для помощи в бою." },
